def _pick(mapping, aliases):
    for k in aliases:
        if isinstance(mapping, dict) and k in mapping:
            return mapping[k]
        if hasattr(mapping, "index") and k in list(mapping.index):
            return mapping[k]
    raise KeyError(f"None of aliases found: {aliases}")

